{"thought": "Testing broad property-based correctness: conservation, negation symmetry, and zero-weight payees always get zero, across many random inputs including negative totals and large weights.", "tool": "run_tests", "tests": [{"name": "test_hypothesis_properties", "code": "import pytest
from hypothesis import given, strategies as st, settings
import impl

@given(
    total_cents=st.integers(min_value=-10**9, max_value=10**9),
    weights=st.lists(st.integers(min_value=0, max_value=10**6), min_size=1, max_size=20)
)
@settings(max_examples=500)
def test_hypothesis_properties(total_cents, weights):
    if sum(weights) == 0:
        with pytest.raises(ValueError):
            impl.allocate(total_cents, weights)
        return
    result = impl.allocate(total_cents, weights)
    assert len(result) == len(weights)
    assert sum(result) == total_cents
    neg_result = impl.allocate(-total_cents, weights)
    assert neg_result == [-x for x in result]
    for w, r in zip(weights, result):
        if w == 0:
            assert r == 0
